window.addEventListener('focus',()=>{if(task&&!running){const before=task.batches.length;receiveFlowResults();if(task.type==='longtext'||task.batches.length!==before)draw()}});
function dirty(){return JSON.stringify(cfg)!==JSON.stringify(task.config)}
function open(t,page='config'){configStep=0;if(t.type==='longtext')root.classList.remove('rd-config-collapsed');taskPage=t.type==='longtext'&&page==='results'?'results':'config';selectedFlowId='';selectedRunId='';targetResourceTab='entity';resourceTab='project';task=t;task.executionMode='agent';task.batches=task.batches||[];task.batches.forEach(b=>{b.events??=[];normalizeTargets(b.config);if(b.status==='执行中')b.status='已停止'});if(!task.config){task.config=initial();if(task.type==='document')task.config.docs=(task.sources||[]).map(name=>({name,status:'就绪',origin:'现有来源'}));else if(task.sources.length){task.config.table=task.sources[0];task.config.fields=task.field?[task.field]:[];}}if(task.config.model==='通用抽取模型')task.config.model='DeepSeek V4';if(task.config.model==='深度推理模型')task.config.model='Qwen3-235B-A22B';task.config.outputDirectory=extractionDirectory();task.config.outputName=task.config.outputName??task.name+'-抽取结果';if(task.type==='longtext')task.config.outputDestination??={space:'个人空间',directory:'数据表'};normalizeTargets(task.config);cfg=copy(task.config);batchIndex=Math.max(0,task.batches.length-1);chat=task.chat||[];resultTab='entity';receiveFlowResults();const requestedRun=new URLSearchParams(location.search).get('run');if(requestedRun&&taskPage==='results'){const record=taskRunRecords().find(r=>r.runId===requestedRun);if(record){selectHistoryRun(record.flowId,record.runId);return}}draw()}
function notice(message){const n=$('rdNotice');if(n)n.textContent=message}
function resultPanel(){return '<section class="rd-panel rd-results" id="rdResults"><header>'+batchDropdown()+(button('导出','export',currentBatch()?.status==='成功'?'':'disabled')+rx('发布数据表','publish',currentBatch()?.status==='成功'?'':'disabled'))+button(window.KnoraReviewUI?.find(task,currentBatch())?'继续校验':'创建校验任务','create-review',currentBatch()?.status==='成功'?'':'disabled')+fullButton()+'</header>'+'<div class="rd-tabs">'+button('实体结果 '+(currentBatch()?.entities.length||0)+publicationBadge(currentBatch(),'entity'),'tab','data-tab="entity" class="btn"')+button('关系结果 '+(currentBatch()?.relations.length||0)+publicationBadge(currentBatch(),'relation'),'tab','data-tab="relation"')+button('事件结果 '+(currentBatch()?.events?.length||0)+publicationBadge(currentBatch(),'event'),'tab','data-tab="event"')+button('图谱展示','tab','data-tab="graph"')+(currentBatch()?.config.customFields?.length?button('自定义结果 '+(currentBatch()?.custom?.length||0),'tab','data-tab="custom"'):'')+'</div><div class="rd-task-status" role="status">'+(running?(task.type==='document'?'Agent 正在抽取文档（模拟）…':'Agent 正在抽取数据表字段（模拟）…'):task.status==='已完成'?'任务已完成，可查看抽取结果':task.status==='运行失败'?'任务运行失败，请检查配置后重试':(task.type==='document'?'点击“保存配置”后自动发送抽取要求，也可在 Agent 区域输入其他要求。':'配置完成后点击“保存配置”，系统会自动发送抽取要求并运行。'))+'</div><div id="rdResultBody" class="rd-result-body">'+results()+'</div></section>'}
function taskRunRecords(){const list=[];for(const flow of submittedFlows()){const records=new Map((flow.runs||[]).map(r=>[r.runId,{...r,flowId:flow.id,flowName:flow.name,workflowName:r.workflowName||flow.workflowName||'—'}]));task.batches.forEach((batch,i)=>{if(batch.flowId!==flow.id)return;const runId=batch.flowRunId||'run-'+i,known=records.get(runId)||{};records.set(runId,{runId,flowId:flow.id,flowName:flow.name,workflowName:flow.workflowName||'—',instanceName:batch.instanceName||flow.name+' · '+runId,runType:batch.runType||'手动运行',status:batch.status==='成功'?'执行成功':batch.status,submittedAt:batch.submittedAt||'',startedAt:batch.startedAt||'',endedAt:batch.endedAt||batch.time||'',...known,hasResult:true})});for(const r of records.values())list.push(r)}return list.sort((a,b)=>(Date.parse(b.submittedAt||b.endedAt)||0)-(Date.parse(a.submittedAt||a.endedAt)||0))}
function selectedRunRecord(){return taskRunRecords().find(r=>r.flowId===selectedFlowId&&r.runId===selectedRunId)}
function runTime(value){if(!value)return '—';return value.includes('T')?new Date(value).toLocaleString('zh-CN',{hour12:false}):value}
function runRecordsTable(){const rows=taskRunRecords();return '<section class="rd-run-list"><header><span>共 '+rows.length+' 条 · 点击记录查看运行结果</span></header><div class="rd-run-table-scroll"><table><thead><tr>'+['任务实例','流程名称','运行类型','任务状态','提交时间','启动时间','结束时间','操作'].map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr data-run-history-row data-flow-id="'+E(r.flowId)+'" data-run-id="'+E(r.runId)+'" class="'+(r.runId===selectedRunId&&r.flowId===selectedFlowId?'selected':'')+'"><td title="'+E(r.instanceName||r.runId)+'"><button class="rd-run-instance" data-rd="run-result" data-flow-id="'+E(r.flowId)+'" data-run-id="'+E(r.runId)+'">'+E(r.instanceName||r.runId)+'</button></td><td title="'+E(r.flowName)+'">'+E(r.flowName)+'</td><td>'+E(r.runType||'手动运行')+'</td><td><span class="rd-run-badge '+(r.status==='执行成功'||r.status==='运行成功'?'success':'')+'">'+E(r.status)+'</span></td><td>'+E(runTime(r.submittedAt))+'</td><td>'+E(runTime(r.startedAt))+'</td><td>'+E(runTime(r.endedAt))+'</td><td>'+runActionIcon('run-rerun','重跑',r,'M20 7v5h-5M20 12a8 8 0 1 0-2 5',rows.some(x=>x.flowId===r.flowId&&x.status==='运行中'))+runActionIcon('run-delete','删除',r,'M4 7h16M9 7V4h6v3M6 7l1 13h10l1-13M10 10v7M14 10v7',r.status==='运行中')+'</td></tr>').join('')+(rows.length?'':'<tr><td colspan="8" class="rd-empty">暂无运行记录，请保存配置并运行任务。</td></tr>')+'</tbody></table></div></section>'}
function runActionIcon(action,label,r,path,disabled=false){return '<button class="rd-run-action" data-rd="'+action+'" data-flow-id="'+E(r.flowId)+'" data-run-id="'+E(r.runId)+'" aria-label="'+label+'" title="'+label+'" '+(disabled?'disabled':'')+'><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="'+path+'" stroke-linecap="round" stroke-linejoin="round"/></svg></button>'}
function syncResultTabs(){document.querySelectorAll('[data-rd="tab"]').forEach(b=>{b.classList.remove('primary');b.setAttribute('role','tab');b.setAttribute('aria-selected',String(b.dataset.tab===resultTab));b.parentElement.setAttribute('role','tablist')})}
function drawTaskDetails(){const records=taskRunRecords();if(!selectedRunRecord()&&records.length){selectedFlowId=records[0].flowId;selectedRunId=records[0].runId}root.innerHTML='<div class="rd-grid '+(task.type==='document'?'rd-document-grid':'rd-document-grid rd-longtext-grid')+'"><div class="rd-top">'+'<button class="rd-back-icon" data-rd="back" title="返回任务列表" aria-label="返回任务列表"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M19 12H5m7-7-7 7 7 7" stroke-linecap="round" stroke-linejoin="round"/></svg></button><strong>'+E(task.name)+'</strong><button class="rd-history-icon" data-rd="run-history" title="运行记录" aria-label="运行记录" aria-haspopup="dialog"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M3 11a9 9 0 1 1 2.6 7M3 5v6h6M12 7v5l3 2" stroke-linecap="round" stroke-linejoin="round"/></svg></button><span class="rd-spacer"></span>'+button('抽取配置','task-config')+'</div><div id="rdNotice" class="rd-notice" role="status"></div><div class="rd-task-detail-view">'+resultPanel()+'</div>';syncResultTabs()}
function showRunHistory(){overlay('运行记录',runRecordsTable(),null,'关闭',true);const dialog=document.querySelector('.rd-overlay');dialog.classList.add('rd-run-history');positionRunHistory();const close=dialog.querySelector('footer [data-rd="close"]');if(close)close.textContent='关闭'}
function positionRunHistory(){const dialog=document.querySelector('.rd-run-history');if(!dialog)return;const rect=root.getBoundingClientRect();dialog.style.left=Math.max(0,rect.left)+'px';dialog.style.top=Math.max(0,Math.min(rect.top,150))+'px'}
function refreshRunHistory(){const container=document.querySelector('.rd-run-history .rd-dialog-body');if(container)container.innerHTML=runRecordsTable()}
function rerunHistory(flowId){try{selectedFlowId=flowId;selectedRunId=window.KnoraExtractionFlowRuntime.rerun(flowId);resultTarget='';draw();refreshRunHistory()}catch(error){const label=$('rdError');if(label)label.textContent=error.message}}
function deleteHistoryRun(flowId,runId){const record=taskRunRecords().find(r=>r.flowId===flowId&&r.runId===runId);if(!record||record.status==='运行中')return;if(!confirm('删除这条运行记录及其结果？关联流程将保留。'))return;try{const key='knora:extraction-flows:v1:'+currentProjectId,flows=JSON.parse(localStorage.getItem(key)||'[]'),flow=flows.find(f=>f.id===flowId);if(flow){flow.runs=(flow.runs||[]).filter(r=>r.runId!==runId);if(flow.lastRunId===runId)flow.lastRunId=flow.runs.at(-1)?.runId||''}localStorage.setItem(key,JSON.stringify(flows));const inboxKey='knora:flow-results:v1:'+currentProjectId;localStorage.setItem(inboxKey,JSON.stringify(JSON.parse(localStorage.getItem(inboxKey)||'[]').filter(r=>!(r.flowId===flowId&&r.runId===runId))));task.batches.forEach((b,i)=>{if(b.flowId&&!b.flowRunId)b.flowRunId='run-'+i});task.batches=task.batches.filter(b=>!(b.flowId===flowId&&b.flowRunId===runId));if(!window.KnoraRulesTasks.persist())throw Error('保存失败，请重试。');if(selectedFlowId===flowId&&selectedRunId===runId){selectedFlowId='';selectedRunId='';resultTarget=''}draw();refreshRunHistory()}catch(error){const label=$('rdError');if(label)label.textContent=error.message}}
window.addEventListener('resize',positionRunHistory);
window.addEventListener('knora:flow-run-update',()=>{if(!task||task.type!=='longtext'||task.executionMode==='agent')return;receiveFlowResults();const record=selectedRunRecord();if(running&&record&&record.status!=='运行中'){running=false;const message=chat.findLast(m=>m.pending);if(message){message.pending=false;message.text=record.status==='执行成功'?'抽取已完成，可在右侧查看结果、核对来源或创建校验任务。':'抽取未完成：'+record.status;if(record.status==='执行成功')message.batch=batchIndex}task.chat=chat;window.KnoraRulesTasks.persist()}draw();refreshRunHistory()});
function selectHistoryRun(flowId,runId){if(!taskRunRecords().some(r=>r.flowId===flowId&&r.runId===runId))return;selectedFlowId=flowId;selectedRunId=runId;resultTarget='';document.querySelector('.rd-overlay')?.remove();draw();root.querySelector('[data-rd="run-history"]')?.focus()}
let configStep=0,configLeft=30;
function draw(){syncResultSchema();root.innerHTML='<div class="rd-grid '+(task.type==='document'?'rd-document-grid':'rd-document-grid rd-longtext-grid')+'"><div class="rd-top">'+button(icon('back'),'back','aria-label="返回任务列表" title="返回任务列表"')+'<strong id="rdTaskName" tabindex="0" title="双击修改任务名称">'+E(task.name)+'</strong>'+'<span class="rt-tag rt-'+task.type+'">'+(task.type==='document'?'文档抽取':'长文本字段抽取')+'</span><span class="rd-spacer"></span><label>LLM <select id="rdModel" '+(running?'disabled':'')+'><option value="">请选择模型</option>'+['DeepSeek V4','DeepSeek V3.2','Qwen3-235B-A22B','Qwen3-32B'].map(n=>'<option '+(cfg.model===n?'selected':'')+'>'+n+'</option>').join('')+'</select></label><small>最近保存：'+E(task.updated)+'</small>'+''+'</div><div id="rdNotice" class="rd-notice" role="status"></div><section class="rd-panel rd-config"><header><span class="rd-config-title">抽取配置'+''+'</span>'+button('<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M14 6l-6 6 6 6"/></svg>','collapse-config','aria-label="收起抽取配置" title="收起抽取配置"')+'</header><fieldset '+(running?'disabled':'')+'><div class="rd-section"><h3>'+ (task.type==='document'?'文档资源':'数据来源')+' <em>*</em></h3>'+sourceConfig()+'</div><div class="rd-section"><h3>抽取目标 <em>*</em></h3>'+targetResources()+'</div><div class="rd-section"><h3>抽取要求</h3><textarea id="rdInstructions" aria-label="抽取要求" placeholder="说明抽取哪些内容、筛选条件和输出格式。&#10;例如：仅抽取已验收的采购记录；金额统一为元；日期使用 YYYY-MM-DD；原文缺失的信息留空，不推测。">'+E(cfg.instructions)+'</textarea></div>'+'</fieldset><footer>'+button('重置','reset',running?'disabled':'')+button(running?'运行中…':'保存配置','save',running?'disabled':'')+'</footer></section>'+documentAgentPanel()+resultPanel()+'</div>';document.querySelectorAll('[data-rd="tab"]').forEach(b=>{b.classList.remove('primary');b.setAttribute('role','tab');b.setAttribute('aria-selected',String(b.dataset.tab===resultTab));b.parentElement.setAttribute('role','tablist');b.parentElement.setAttribute('aria-label','抽取结果类型')});syncConfigToggle();if(task.type==='longtext'){const flow=root.querySelector('.rd-config-flow-icon');if(flow)root.querySelector('.rd-top').append(flow);}const chatBox=$('rdChat');if(chatBox)chatBox.scrollTop=chatBox.scrollHeight;}

function sourceSamples(name){return name==='supplier_feedback'?[[18,'供应商华东精工提供精密轴承，批次 B-018 已完成验收。','到货及时，包装完好','华东精工','2026-10-12 09:30:00','12500.00'],[19,'华南制造交付传动轴，需补充批次 B-019 的质检报告。','待补充报告','华南制造','2026-10-12 10:15:00','8600.00'],[20,'供应商华东精工本月交付合格率为 99.2%。','建议维持合作等级','华东精工','2026-10-12 11:20:00','19200.00'],[21,'北方机电交付轴承组件，发现两件包装破损，需要复检。','安排复检','北方机电','2026-10-13 08:40:00','7300.00'],[22,'华南制造完成补发，批次 B-022 数量与订单一致。','验收通过','华南制造','2026-10-13 14:10:00','9600.00']]:[[18,'批次 B-018 外观和尺寸检验合格，无异常。','B-018',98],[19,'批次 B-019 发现轻微表面划痕，建议复检。','B-019',85],[20,'批次 B-020 抽样检验通过，允许入库。','B-020',96],[21,'批次 B-021 包装破损，待复检。','B-021',82],[22,'批次 B-022 复检合格。','B-022',97]]}
function inlineSourcePreview(){const t=tables.find(x=>x.name===cfg.table);if(!t)return '';return '<div class="lt-source-fields"><div class="lt-source-fields-heading"><strong>抽取字段 <small>· '+cfg.fields.length+' 个</small></strong><button type="button" class="lt-source-icon-btn" data-rd="source-fields" title="编辑抽取字段" aria-label="编辑抽取字段"><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m15 5 4 4M4 20l4-1L20 7a2.8 2.8 0 0 0-4-4L4 15zM13 20h7"/></svg></button></div>'+(cfg.fields.length?'<div class="lt-field-chips">'+cfg.fields.map(n=>'<span class="lt-field-chip">'+E(n)+'<small>· '+E(t.fields.find(f=>f[0]===n)?.[1]||'TEXT')+'</small></span>').join('')+'</div>':'<p class="lt-fields-warning">请先选择至少一个文本字段</p>')+'</div>'}
function configStepsMarkup(){const count=cfg.entities.length+cfg.relations.length+cfg.events.length+cfg.customFields.length;return [['数据来源',cfg.table?(cfg.table+' · '+cfg.fields.length+' 个抽取字段'):'选择数据表与抽取字段',!!cfg.table&&!!cfg.fields.length],['抽取目标','实体 '+cfg.entities.length+' · 关系 '+cfg.relations.length+' · 事件 '+cfg.events.length+' · 自定义 '+cfg.customFields.length,!!count],['抽取规则',cfg.model||'选择模型与填写抽取要求',!!cfg.model],['结果保存',cfg.outputName?'个人空间 / 数据表':'选填 · 不保存结果资源',!!cfg.outputName]].map(([name,summary,done],i)=>'<button type="button" data-config-step="'+i+'" aria-current="'+(i===configStep?'step':'false')+'"><span class="lt-step-number">'+(i+1)+'</span><span><strong>'+name+'</strong><small>'+E(summary)+'</small><small>'+ (done?'已配置':i===3?'选填':'待配置')+'</small></span></button>').join('')}
function refreshConfigSteps(){const nav=root.querySelector('.lt-config-steps');if(nav)nav.innerHTML='<h3>配置步骤</h3>'+configStepsMarkup()}
function layoutLongtextConfig(){const grid=root.querySelector('.rd-config-only'),panel=grid?.querySelector('.rd-config');if(!panel)return;grid.classList.add('lt-config-layout');grid.style.setProperty('--lt-config-left',configLeft+'%');const nav=document.createElement('nav');nav.className='lt-config-steps';nav.setAttribute('aria-label','长文本抽取配置步骤');grid.prepend(nav);const divider=document.createElement('button');divider.type='button';divider.className='lt-config-divider';divider.setAttribute('role','separator');divider.setAttribute('aria-orientation','vertical');divider.setAttribute('aria-label','拖动调整左右栏宽度，方向键微调');divider.setAttribute('aria-valuemin','25');divider.setAttribute('aria-valuemax','40');divider.setAttribute('aria-valuenow',configLeft);divider.innerHTML='<span>⋮</span>';nav.after(divider);const sections=[...panel.querySelector('fieldset').children];sections.forEach((section,i)=>{section.hidden=i!==configStep;section.dataset.configPanel=i});sections[0].insertAdjacentHTML('beforeend',inlineSourcePreview());const model=$('rdModel')?.closest('label');if(model){model.classList.add('lt-config-model');sections[2].insertBefore(model,sections[2].children[1])}sections[2].querySelector('h3').textContent='抽取规则';panel.querySelector('header .rd-config-title').firstChild.textContent=['数据来源','抽取目标','抽取规则','结果保存'][configStep];const detailButton=root.querySelector('.rd-top [data-rd="task-details"]');if(detailButton){detailButton.innerHTML='<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9zM14 3v6h6M8 13h8M8 17h6" stroke-linecap="round" stroke-linejoin="round"/></svg>';detailButton.classList.add('lt-top-icon');detailButton.setAttribute('title','运行结果');detailButton.setAttribute('aria-label','运行结果');const flowIcon=panel.querySelector('.rd-config-flow-icon');if(flowIcon){flowIcon.classList.add('lt-top-icon');detailButton.before(flowIcon)}}const footer=panel.querySelector('footer');footer.insertAdjacentHTML('afterbegin',button('上一步','config-prev',configStep===0?'disabled':'')+button('下一步','config-next',configStep===3?'disabled':''));refreshConfigSteps();const changeWidth=value=>{configLeft=Math.max(25,Math.min(40,value));grid.style.setProperty('--lt-config-left',configLeft+'%');divider.setAttribute('aria-valuenow',configLeft)};divider.addEventListener('pointerdown',e=>{divider.setPointerCapture(e.pointerId);e.preventDefault()});divider.addEventListener('pointermove',e=>{if(!divider.hasPointerCapture(e.pointerId))return;const rect=grid.getBoundingClientRect();changeWidth(Math.round((e.clientX-rect.left)/rect.width*100))});divider.addEventListener('pointerup',e=>{if(divider.hasPointerCapture(e.pointerId))divider.releasePointerCapture(e.pointerId)});divider.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();changeWidth(configLeft+(e.key==='ArrowRight'?1:-1))}})}
document.addEventListener('click',e=>{const b=e.target.closest('[data-config-step],[data-rd="config-prev"],[data-rd="config-next"]');if(!b||b.disabled||task?.type!=='longtext')return;if(b.dataset.configStep!==undefined)configStep=Number(b.dataset.configStep);else configStep=Math.max(0,Math.min(3,configStep+(b.dataset.rd==='config-next'?1:-1)));draw()});
