function overlay(title,body,action,label='确认',wide=false){document.querySelector('.rd-overlay')?.remove();const o=document.createElement('div');o.className='rd-overlay';o.innerHTML='<section class="rd-dialog '+(wide?'wide':'')+'" role="dialog" aria-modal="true" aria-label="'+E(title)+'"><header><h2>'+E(title)+'</h2>'+button('×','close')+'</header><div class="rd-dialog-body">'+body+'</div><p id="rdError" role="alert"></p><footer>'+button('取消','close')+(action?button(label,action):'')+'</footer></section>';document.body.appendChild(o);o.querySelector('button').focus()}
function scopeCustomBody(){return '<div class="rd-tabs">'+[['entity','实体',scope.entities.length],['relation','关系',scope.relations.length],['event','事件',scope.events.length],['custom','自定义结构',scope.customFields.length]].map(([tab,name,count])=>button(name+' '+count,'scope-tab','data-tab="'+tab+'" aria-pressed="'+(tab==='custom')+'"')).join('')+'</div><div class="scope-custom-body"><h3>自定义抽取结构</h3><p class="rd-muted">按需要添加字段，例如供应商名称、采购金额、交付日期。字段名称不可重复。</p><div class="scope-custom-labels '+(true?'document-custom-columns':'')+'"><span>字段名称</span>'+(true?'<span>类型</span><span>描述</span>':'')+'<span>操作</span></div>'+scope.customFields.map((f,i)=>'<div class="scope-custom-row '+(true?'document-custom-columns':'')+'"><input data-scope-custom-name="'+i+'" aria-label="字段名称" placeholder="请输入字段名称" value="'+E(f.name)+'">'+(true?'<select data-scope-custom-type="'+i+'" aria-label="字段类型">'+['文本','数值','日期','布尔'].map(t=>'<option '+((f.type||'文本')===t?'selected':'')+'>'+t+'</option>').join('')+'</select><input data-scope-custom-description="'+i+'" aria-label="字段描述" placeholder="说明字段含义或抽取要求" value="'+E(f.description||'')+'">':'')+button(deleteFieldIcon,'scope-custom-remove','data-index="'+i+'" aria-label="删除字段" title="删除字段"')+'</div>').join('')+(scope.customFields.length?'':'<div class="rd-resource-empty">暂无自定义字段，点击下方添加</div>')+'<button class="rd-resource-add" data-rd="scope-custom-add">⊕ 添加字段</button></div>'}
function scopeBody(){if(scopeTab==='custom')return scopeCustomBody();const items=scopeTab==='entity'?entities:scopeTab==='relation'?relations:events,selected=scopeTab==='entity'?scope.entities:scopeTab==='relation'?scope.relations:scope.events;const description=(x,i)=>scopeTab==='entity'?x[1]:scopeTab==='relation'?entities[x[1]][0]+' → '+entities[x[2]][0]:x[1].map(e=>entities[e][0]).join(' + ');const filtered=items.map((x,i)=>({x,i})).filter(({x,i})=>(x[0]+' '+description(x,i)).includes(scopeQuery));const pages=Math.max(1,Math.ceil(filtered.length/5));scopePage=Math.min(scopePage,pages);return '<div class="rd-tabs">'+[['entity','实体',scope.entities,entities],['relation','关系',scope.relations,relations],['event','事件',scope.events,events],['custom','自定义结构',scope.customFields,scope.customFields]].map(([tab,name,chosen,all])=>button(name+' '+chosen.length+'/'+all.length,'scope-tab','data-tab="'+tab+'" aria-pressed="'+(scopeTab===tab)+'"')).join('')+'</div><input id="rdScopeSearch" placeholder="搜索实体、关系、事件或描述" value="'+E(scopeQuery)+'"><div class="rd-summary"><label><input id="rdAll" type="checkbox"> 全选本页</label><span>已选择 '+selected.length+' 项</span></div><div class="rd-scope-layout"><div>'+filtered.slice((scopePage-1)*5,scopePage*5).map(({x,i})=>'<div class="rd-scope-row"><input type="checkbox" aria-label="选择'+E(x[0])+'" data-scope-item="'+i+'" '+(selected.includes(i)?'checked':'')+'><span><b>'+x[0]+'</b><small>'+description(x,i)+'</small></span>'+button('配置属性','properties','data-index="'+i+'" '+(selected.includes(i)?'':'disabled'))+'</div>').join('')+(filtered.length?'':'<p class="rd-muted">暂无匹配目标</p>')+'</div>'+(propFocus===null?'':propertyPanel())+'</div><div class="rd-summary">共 '+filtered.length+' 条 '+button('上一页','scope-prev',scopePage===1?'disabled':'')+scopePage+' / '+pages+button('下一页','scope-next',scopePage===pages?'disabled':'')+'</div>'}
function propertyPanel(){const i=propFocus,key=targetKey(scopeTab,i),req=scope.requirements[key]||'',mandatory=targetRequired(scopeTab,i),fields=targetFields(scopeTab,i),name=(scopeTab==='entity'?entities:scopeTab==='relation'?relations:events)[i][0];return '<aside class="rd-properties"><h3>'+name+'</h3><p class="rd-muted">'+(scopeTab==='entity'?'实体主键唯一，必须抽取。':scopeTab==='relation'?'起点、终点实体主键共同组成联合主键，两项必须抽取。':'所有归属实体的主键共同组成事件联合主键，全部必须抽取。')+'</p>'+fields.map(p=>'<label class="rd-check"><input type="checkbox" data-prop="'+E(p)+'" '+((scope.props[key]||[]).includes(p)?'checked':'')+' '+(mandatory.includes(p)?'disabled':'')+'><span>'+E(p)+'</span><small>'+(mandatory.includes(p)?(scopeTab==='entity'?'主键 · 必选':'联合主键 · 必选'):'可选属性')+'</small></label>').join('')+'</aside>'}
function drawScope(){document.querySelector('.rd-dialog-body').innerHTML=scopeBody();const checks=[...document.querySelectorAll('[data-scope-item]')],all=$('rdAll');if(!all)return;all.checked=checks.length>0&&checks.every(x=>x.checked);all.indeterminate=checks.some(x=>x.checked)&&!all.checked;}
function selectItem(i,on){const field=scopeTab==='entity'?'entities':scopeTab==='relation'?'relations':'events';if(scopeTab==='entity'&&!on){const rs=scope.relations.filter(r=>relations[r].slice(1).includes(i)),es=scope.events.filter(e=>events[e][1].includes(i));if((rs.length||es.length)&&!confirm('取消该实体将同时取消关联目标：'+[...rs.map(r=>relations[r][0]),...es.map(e=>events[e][0])].join('、')+'。是否继续？'))return;scope.relations=scope.relations.filter(r=>!rs.includes(r));scope.events=scope.events.filter(e=>!es.includes(e))}if(on){if(!scope[field].includes(i))scope[field].push(i);if(scopeTab!=='entity'){const deps=scopeTab==='relation'?relations[i].slice(1):events[i][1];deps.forEach(e=>{if(!scope.entities.includes(e))scope.entities.push(e)})}normalizeTargets(scope)}else{scope[field]=scope[field].filter(x=>x!==i);if(propFocus===i)propFocus=null}}
function validate(){if(!cfg.model)return '请选择模型。';if(task.type==='document'&&!cfg.docs.length)return '请添加至少一个文档。';if(task.type==='longtext'&&(!cfg.table||!cfg.fields.length))return '请选择数据表和主要抽取字段。';if(!cfg.entities.length)return '请选择抽取目标。';return ''}
function documentAgentPanel(){return '<section class="rd-panel rd-agent" aria-label="抽取对话"><div class="rd-chat" id="rdChat">'+(chat.length?chat.map((m,i)=>chatMessage(m,i)).join(''):'<div class="rd-empty">'+(task.type==='longtext'?'长文本字段抽取助手':'文档抽取助手')+'<br><small>发送抽取要求开始任务，完成后可继续追问、调整结果。</small></div>')+'</div><div class="rd-compose"><textarea id="rdMessage" placeholder="请输入抽取要求或追问内容" '+(running?'disabled':'')+'></textarea><div>'+ (running?button('停止抽取','stop'):button('<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M4 4l17 8-17 8 3-8-3-8zm3 8h14"/></svg>','send','aria-label="发送抽取要求" title="发送抽取要求"'))+'</div></div></section>'}
function runDocument(request=''){if(running)return;syncResultSchema();const error=flowConfigurationError();if(error){chat.push({role:'agent',text:error});task.chat=chat;window.KnoraRulesTasks.persist();draw();return}if(!save()){notice('配置保存失败，请重试。');return}task.executionMode='agent';running=true;task.status='执行中';const config=copy(cfg);if(task.type==='longtext')config.sourceSnapshot={fields:copy(tables.find(t=>t.name===config.table)?.fields||[]),rows:copy(sourceSamples(config.table))};for(const f of config.outputSchema.filter(f=>f.origin==='target'&&f.kind!=='custom')){const key=targetKey(f.kind,f.target);config.props[key]=[...new Set([...(config.props[key]||[]),f.name])]}const b={time:new Date().toLocaleString('zh-CN'),status:'执行中',config,request:request||cfg.instructions,entities:[],relations:[],events:[],custom:[]};task.batches.push(b);batchIndex=task.batches.length-1;resultTarget='';chat.push({role:'agent',text:task.type==='document'?'正在按本次要求抽取文档，完成后将在右侧展示结果。':'正在按本次配置抽取数据表字段，完成后将在右侧展示本轮结果。',batch:batchIndex,phase:'progress'});task.chat=chat;if(!window.KnoraRulesTasks.persist()){running=false;b.status='失败';task.status='运行失败';draw();notice('任务保存失败，请重试。');return}draw();timer=setTimeout(()=>{try{fillBatch(b,2);b.custom=(config.customFields.length?[0,1]:[]).map((_,i)=>({target:0,type:'自定义结构',name:'记录 '+(i+1),props:Object.fromEntries(config.customFields.map(f=>[f.name,f.type==='数值'?String((i+1)*100):f.type==='日期'?'2026-10-16':f.type==='布尔'?(i?'否':'是'):f.name+'示例'+(i+1)])),source:task.type==='document'?config.docs[i%config.docs.length].name:'数据表 '+config.table+' / id='+(i+18),evidence:task.type==='document'?'自定义结构示例记录':String(config.sourceSnapshot?.rows[i]?.[config.sourceSnapshot.fields.findIndex(f=>f[0]===config.fields[0])]||'')}));if(/主键.*(缺失|为空|空值)|缺失.*主键/.test(b.request)){for(const kind of ['entity','relation','event']){const record=collection(b,kind)[0];if(record){const key=recordKeys(record,kind)[0];if(key)record.props[key]=''}}b.mockMissingKeys=true}b.outputTables=window.KnoraResultSchema.tables(b);preserveRawResult(b);if(!b.rawSaved&&!b.rawSkipped)throw Error('结果保存失败');b.status='成功';task.status='已完成';chat.push({role:'agent',text:(task.type==='document'?'文档抽取':'长文本字段抽取')+'完成。可在右侧查看本轮结果和图谱，也可以继续追问、修改结果或发布数据表。',batch:task.batches.indexOf(b),phase:'complete'});if(!window.KnoraRulesTasks.persist())throw Error('任务保存失败')}catch(error){b.status='失败';task.status='运行失败';chat.push({role:'agent',text:'抽取失败：'+error.message+'。请重试。'});window.KnoraRulesTasks.persist()}finally{running=false;draw()}},1200)}
function run(request=''){runDocument(request)}
function editRecord(index){const b=currentBatch();editor={index,kind:resultTab};const r=index===null?{name:'',type:resultTab==='entity'?entities[b.config.entities[0]][0]:relations[b.config.relations[0]??0][0],props:{}}:copy((resultTab==='entity'?b.entities:b.relations)[index]);editor.record=r;editorBody()}
function editorBody(){const r=editor.record,b=currentBatch();const types=editor.kind==='entity'?b.config.entities.map(i=>entities[i][0]):b.config.relations.map(i=>relations[i][0]);if(!types.length){notice('当前批次配置未选择关系，不能新增关系。');return}if(editor.kind==='entity'){const i=entities.findIndex(x=>x[0]===r.type);for(const p of b.config.props[i]||entities[i][2])r.props[p]??='';}overlay('编辑'+(editor.kind==='entity'?'实体':'关系'),'<label>类型<select id="rdEditType">'+types.map(t=>'<option '+(r.type===t?'selected':'')+'>'+t+'</option>').join('')+'</select></label><label>名称<input id="rdEditName" value="'+E(r.name)+'"></label>'+(editor.kind==='entity'?Object.entries(r.props).map(([k,v])=>'<label>'+E(k)+(required(entities.findIndex(x=>x[0]===r.type)).includes(k)?' *':'')+'<input data-edit-prop="'+E(k)+'" value="'+E(v)+'"></label>').join(''):'<label>起点<select id="rdFrom">'+b.entities.filter(e=>e.type===entities[relations.find(x=>x[0]===r.type)[1]][0]).map(e=>'<option '+(r.from===e.name?'selected':'')+'>'+E(e.name)+'</option>').join('')+'</select></label><label>终点<select id="rdTo">'+b.entities.filter(e=>e.type===entities[relations.find(x=>x[0]===r.type)[2]][0]).map(e=>'<option '+(r.to===e.name?'selected':'')+'>'+E(e.name)+'</option>').join('')+'</select></label>'),'save-record','保存')}
async function upload(files){const errors=[];for(const f of files){if(!/\.(pdf|docx?|pptx?|txt)$/i.test(f.name)||f.size>50*1024*1024||!f.size){errors.push(f.name+'：格式不支持、空文件或超过 50 MB');continue}if(!cfg.docs.some(d=>personal(d)&&d.name===f.name&&d.size===f.size))cfg.docs.push({name:f.name,resourceType:'personal',status:'就绪',origin:'本地上传',size:f.size})}draw();notice(errors.join('；')||'文件已加入个人资源列表。')}
