let sourceView=null;
function openSource(batch,record){const names=[...new Set((batch.config.docs||[]).map(d=>d.name))];if(record.source&&!names.includes(record.source))names.push(record.source);if(!names.length)names.push('人工补充');sourceView={batch,record,names,active:Math.max(0,names.indexOf(record.source))};overlay('结果来源','<div id="rxSourceViewer"></div>',null,'',true);document.querySelector('.rd-dialog').classList.add('rx-source-dialog');renderSource()}
function sourceSentenceMarkup(value,evidence){const text=String(value??'—'),candidates=String(evidence||'').replace(/^示例原文：/,'').split(/(?<=[。！？.!?])/).map(x=>x.trim()).filter(x=>x.length>5),sentence=candidates.find(x=>text.includes(x));if(!sentence)return E(text);const at=text.indexOf(sentence);return E(text.slice(0,at))+'<mark class="rx-source-sentence-hit">'+E(sentence)+'</mark>'+E(text.slice(at+sentence.length))}

function tableSourcePreview(){const {batch,record}=sourceView,name=batch.config.table||'数据表',table=tables.find(t=>t.name===batch.config.table),fields=batch.config.sourceSnapshot?.fields||table?.fields||[],match=(record.source||'').match(/id\s*=\s*(\d+)/i),wanted=match?Number(match[1]):NaN,sampleRows=batch.config.sourceSnapshot?.rows||sourceSamples(batch.config.table),row=sampleRows.find(r=>Number(r[0])===wanted),isHit=!!row;return '<div class="rx-source-toolbar"><span>数据表 '+E(name)+'<small> · '+E(table?.db||'业务数据')+' · 二维表记录</small></span>'+rx('查看抽取字段','source-locate',isHit?'':'disabled')+'</div><div class="rx-source-scroll" id="rxSourceScroll"><div class="rx-source-table-wrap"><table class="rx-source-table"><thead><tr>'+fields.map(([field,type])=>'<th class="'+((batch.config.fields||[]).includes(field)?'rx-source-selected':'')+'">'+E(field)+'<small>'+E(type)+'</small></th>').join('')+'</tr></thead><tbody><tr id="rxSourceHit" tabindex="-1">'+fields.map(([field],i)=>'<td class="'+((batch.config.fields||[]).includes(field)?'rx-source-selected':'')+'">'+((batch.config.fields||[]).includes(field)?sourceSentenceMarkup(row?.[i],record.evidence):E(row?.[i]??'—'))+'</td>').join('')+'</tr></tbody></table></div></div><div class="rx-source-footer">来源记录：'+E(record.source||name)+(isHit?'；仅高亮与抽取证据匹配的内容。':'；未找到对应来源记录，无法展示原始值。')+'</div>'}function sourcePreview(){if(task.type==='longtext')return tableSourcePreview();const {batch,record,names,active}=sourceView,name=names[active],rows=['entity','relation','event','custom'].flatMap(k=>collection(batch,k)).filter(r=>r.source===name&&r.evidence);const texts=[...new Set(rows.map(r=>r.evidence))];const matches=name===record.source&&!!record.evidence;const manual=name==='人工补充';return '<div class="rx-source-tabs" role="tablist" aria-label="来源文件">'+names.map((n,i)=>'<button role="tab" aria-selected="'+(i===active)+'" data-rx="source-file" data-index="'+i+'" title="'+E(n)+'">'+E(n)+'</button>').join('')+'</div><div class="rx-source-toolbar"><span>'+E(name)+'<small> · '+(manual?'人工补充记录':'示例文档预览')+'</small></span>'+rx('定位出处','source-locate',matches?'':'disabled')+'</div><div class="rx-source-scroll" id="rxSourceScroll"><article class="rx-source-paper"><h2>'+E(name.replace(/\.[^.]+$/,''))+'</h2><p class="rx-source-note">'+(manual?'此结果由人工补充，暂无对应文件出处。':'以下为原型演示内容，用于展示文件预览与出处定位效果。')+'</p>'+(manual?'':'<h3>一、业务背景</h3><p>本文件用于记录采购业务、物料供应及批次验收信息，支持业务过程追溯。</p><h3>二、业务记录</h3>'+ (texts.length?texts.map((text,i)=>'<section class="rx-source-paragraph"><span class="rx-source-line">段落 '+(i+1)+'</span><p '+(matches&&text===record.evidence?'id="rxSourceHit" class="rx-source-hit" tabindex="-1"':'')+'>'+E(text.replace(/^示例原文：/,''))+'</p></section>').join(''):'<p class="rx-source-note">此文件暂无可预览的抽取片段。</p>')+'<h3>三、记录说明</h3><p>业务记录中的实体标识与关联信息用于追踪对应物料、供应商和批次。</p>')+'</article></div><div class="rx-source-footer">'+(matches?'已定位至当前结果出处，黄色区域为引用内容':'当前文件无此条结果的出处')+'</div>'}
function renderSource(){$('rxSourceViewer').innerHTML=sourcePreview();locateSource()}
function locateSource(){const hit=document.querySelector('#rxSourceViewer .rx-source-sentence-hit')||$('rxSourceHit'),scroll=$('rxSourceScroll');if(hit&&scroll){scroll.scrollTop=Math.max(0,hit.getBoundingClientRect().top-scroll.getBoundingClientRect().top+scroll.scrollTop-90);hit.scrollIntoView({block:'center',inline:'nearest'});hit.setAttribute('tabindex','-1');hit.focus({preventScroll:true})}}
