let pendingDelete=null;
function chatMessage(m,i){const b=Number.isInteger(m.batch)?task.batches[m.batch]:null;const done=m.phase==='complete'||(b?.status==='成功'&&m.phase!=='progress');return '<article class="rd-message '+m.role+'"><div class="rx-answer-text">'+E(m.text).replace(/\n/g,'<br>')+'</div>'+(m.question&&!m.resolved?'<div class="rx-answer-options">'+m.options.map((option,n)=>rx(E(option),'answer','data-message="'+i+'" data-option="'+n+'" '+(running?'disabled':''))).join('')+'</div>':'')+(done?'<div class="rx-chat-summary"><b>抽取结果汇总</b><ul><li>实体：'+collection(b,'entity').length+' 条</li><li>关系：'+collection(b,'relation').length+' 条</li><li>事件：'+collection(b,'event').length+' 条</li></ul></div>':'')+(b&&m.phase!=='progress'?rx('查看本轮结果','batch','data-index="'+m.batch+'"'):'')+'</article>'}
function modifyReturnedResult(text){const base=currentBatch();if(!base||base.status!=='成功'||/重新抽取|重新运行|开始抽取/.test(text)||!/修改|改为|设为|去重|优化|合并/.test(text))return false;chat.push({role:'user',text});const match=text.match(/(?:将|把)?[“"]?([^“”"，。]+?)[”"]?(?:改为|设为)[“"]?([^“”"，。]+)[”"]?/);let changed=0;const next=copy(base);if(match){const field=match[1].trim().replace(/^修改/,''),value=match[2].trim();for(const kind of ['entity','relation','event','custom'])for(const record of collection(next,kind))if(Object.hasOwn(record.props,field)){record.props[field]=value;changed++}}else if(/按主键.*(去重|合并)|去重/.test(text)){for(const kind of ['entity','relation','event']){const seen=new Set();next[bucket(kind)]=collection(next,kind).filter(r=>{const keys=recordKeys(r,kind);if(!keys.length||keys.some(k=>!r.props[k]))return true;const key=r.type+JSON.stringify(keys.map(k=>r.props[k]));if(seen.has(key)){changed++;return false}seen.add(key);return true})}}if(changed){next.parentFlowRunId=base.flowRunId;next.flowRunId=undefined;delete next.publication;delete next.rawResult;delete next.outputTables;next.edited=true;next.time=new Date().toLocaleString('zh-CN');next.request=text;task.batches.push(next);batchIndex=task.batches.length-1;chat.push({role:'agent',text:'已基于抽取结果完成 '+changed+' 项调整，生成新的结果批次，原始结果保留。',batch:batchIndex})}else chat.push({role:'agent',text:'请明确需要修改的字段和值，例如“将检验结果改为待复核”，或输入“按主键去重”。也可以直接在右侧编辑记录。当前未更改抽取结果。'});task.chat=chat;window.KnoraRulesTasks.persist();draw();return true}
function saveAndSendExtraction(){if(running)return;const feedback=text=>{chat.push({role:'agent',text});task.chat=chat;window.KnoraRulesTasks.persist();draw();notice(text)};try{const model=$('rdModel'),instructions=$('rdInstructions');if(model)cfg.model=model.value;if(instructions)cfg.instructions=instructions.value;const error=flowConfigurationError();if(error){feedback('配置尚未提交：'+error);return}if(!save()){feedback('配置保存失败，请重试。');return}const prompt=task.type==='longtext'?'基于配置的内容完成长文本字段抽取':'基于配置的内容完成文档抽取';submitQuestion(prompt,{fromConfig:true})}catch(error){running=false;feedback('提交失败：'+error.message)}}
function submitQuestion(text,{fromConfig=false}={}){if(fromConfig){chat.forEach(m=>{if(m.question&&!m.resolved)m.resolved=true});chat.push({role:'user',text});task.chat=chat;if(!window.KnoraRulesTasks.persist())throw Error('抽取命令保存失败，请重试。');draw();run(text);return}if(modifyReturnedResult(text))return;const question=[...chat].reverse().find(m=>m.question&&!m.resolved);chat.push({role:'user',text});if(question){question.resolved=true;task.chat=chat;window.KnoraRulesTasks.persist();if(/取消|暂不|不执行/.test(text)){chat.push({role:'agent',text:'好的，暂不执行抽取。你可以调整左侧配置，或继续输入新的要求。'});window.KnoraRulesTasks.persist();draw();return}if(text==='使用示例配置继续')cfg=demoConfig(cfg);run(question.request+'；用户确认：'+text);return}if(/多少|有哪些|查看|来源|为什么/.test(text)&&task.batches.some(b=>b.status==='成功')&&!/抽取|重新|补充|开始/.test(text)){const index=task.batches.findLastIndex(b=>b.status==='成功'),b=task.batches[index];chat.push({role:'agent',text:'最近一轮包含 '+collection(b,'entity').length+' 条实体、'+collection(b,'relation').length+' 条关系和 '+collection(b,'event').length+' 条事件。点击下方查看结果，各条记录的“来源”可以查看文档或数据表信息。',batch:index});task.chat=chat;window.KnoraRulesTasks.persist();draw();return}const missing=(!cfg.model||(task.type==='document'?!cfg.docs.length:!cfg.table)||(!cfg.entities.length&&!cfg.relations.length&&!cfg.events.length&&!cfg.customFields.length));const ambiguous=/重复|去重|合并|不确定|确认/.test(text);if(missing||ambiguous){chat.push({role:'agent',text:missing?'当前配置尚未完整。是否使用演示文档、模型和抽取目标继续？':'执行前需要确认：遇到相同主键的记录，采用哪种处理方式？',question:true,request:text,options:missing?['使用示例配置继续','暂不执行，先配置']:['按主键合并','保留首条记录','暂不执行']});task.chat=chat;window.KnoraRulesTasks.persist();draw();return}task.chat=chat;window.KnoraRulesTasks.persist();run(text)}
document.addEventListener('click',e=>{const el=e.target.closest('[data-rx="answer"]');if(!el||running)return;const m=chat[Number(el.dataset.message)];if(!m||m.resolved)return;submitQuestion(m.options[Number(el.dataset.option)])});
let resultTarget='',recordEdit=null;
const rx=(text,action,extra='')=>'<button class="btn" data-rx="'+action+'" '+extra+'>'+text+'</button>';
const bucket=k=>k==='entity'?'entities':k==='relation'?'relations':k==='custom'?'custom':'events';
const collection=(b,k=resultTab)=>b[bucket(k)]||[];
const definitions=k=>k==='entity'?entities:k==='relation'?relations:k==='custom'?[['自定义结构']]:events;
const selectedTargets=(b,k=resultTab)=>k==='custom'?(b.config.customFields?.length?[0]:[]):b.config[bucket(k)]||[];
const recordTarget=(r,k=resultTab)=>r.target??definitions(k).findIndex(x=>x[0]===r.type);
const recordKeys=(r,k=resultTab)=>k==='custom'?[]:recordTarget(r,k)<0?[]:targetRequired(k,recordTarget(r,k));
function validatePublication(b){if(!b||b.status!=='成功'){notice('请先完成抽取再发布。');return false}const problems=[];for(const kind of ['entity','relation','event','custom'])collection(b,kind).forEach((r,i)=>{const error=issues(b,kind,r);if(error)problems.push({kind,index:i,type:r.type,error,fields:recordKeys(r,kind).filter(k=>!String(r.props[k]??'').trim())})});if(!problems.length)return true;overlay('发布校验未通过','<p>存在 '+problems.length+' 条主键问题，无法发布。请补全实体主键及关系、事件的全部联合主键字段。</p><div class="publish-errors">'+problems.map(p=>'<div><b>'+E(p.type)+' · 第 '+(p.index+1)+' 条</b><small>'+E(p.error)+(p.fields.length?'：'+p.fields.map(E).join('、'):'')+'</small>'+rx('去补充','fix-key','data-kind="'+p.kind+'" data-index="'+p.index+'"')+'</div>').join('')+'</div>',null);return false}
function issues(b,k,r){const keys=recordKeys(r,k);if(keys.some(x=>!String(r.props[x]??'').trim()))return '主键待补充';if(collection(b,k).some(x=>x!==r&&x.type===r.type&&keys.length&&keys.every(key=>x.props[key]===r.props[key])))return '主键重复';return ''}
